<?php require_once __DIR__.'/_common.php';$years=ns_years($pdo);$year=ns_year($years);$event=substr(trim((string)($_GET['event']??'')),0,80);$events=[];$selected=null;$ratings=[];if($year){$s=$pdo->prepare('SELECT tba_event_key,name,start_date,end_date FROM augur_epa_archive_events WHERE season_year=? ORDER BY start_date,name');$s->execute([$year]);$events=$s->fetchAll(PDO::FETCH_ASSOC);foreach($events as $e){if($event===$e['tba_event_key'])$selected=$e;}if($selected){$s=$pdo->prepare('SELECT frc_team_number,rating,auto_rating,teleop_rating,endgame_rating FROM augur_epa_event_ratings WHERE tba_event_key=? ORDER BY rating DESC');$s->execute([$event]);$ratings=$s->fetchAll(PDO::FETCH_ASSOC);}}ns_head('Event Analytics');?><section class="page-intro"><span class="eyebrow">EVENT EXPLORER</span><h1>Event <em>Analytics.</em></h1><p>Explore archived events and team EPA ratings. All figures come from public match information.</p></section><section class="panel"><div class="section-top"><h2>Select an event</h2><?php ns_select_year($years,$year,'/epa/events.php');?></div><label for="event">Event</label><form method="get" class="filter event-filter"><input type="hidden" name="year" value="<?=$year?>"><select id="event" name="event"><option value="">All archived events</option><?php foreach($events as $ev):?><option value="<?=ns_h($ev['tba_event_key'])?>" <?=$selected&&$selected['tba_event_key']===$ev['tba_event_key']?'selected':''?>><?=ns_h($ev['name'])?></option><?php endforeach;?></select><button>View event</button></form></section><?php if($selected):?><section class="panel"><span class="eyebrow"><?=ns_h($selected['tba_event_key'])?></span><h2><?=ns_h($selected['name'])?></h2><p class="muted"><?=ns_h($selected['start_date'])?> – <?=ns_h($selected['end_date'])?></p><div class="table-scroller"><table><thead><tr><th>EPA Rank</th><th>Team</th><th>EPA</th><th>Auto</th><th>Teleop</th><th>Endgame</th></tr></thead><tbody><?php foreach($ratings as $i=>$r):?><tr><td><?=$i+1?></td><td><a href="/epa/team.php?team=<?=intval($r['frc_team_number'])?>&year=<?=$year?>">#<?=intval($r['frc_team_number'])?></a></td><?php foreach(['rating','auto_rating','teleop_rating','endgame_rating'] as $k):?><td><?=ns_n($r[$k])?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php if(!$ratings)ns_blank();?></section><?php else:?><section class="panel"><h2><?=$year?> events</h2><div class="event-grid"><?php foreach($events as $ev):?><a class="event" href="?year=<?=$year?>&event=<?=rawurlencode($ev['tba_event_key'])?>"><b><?=ns_h($ev['name'])?></b><span><?=ns_h($ev['start_date']??'')?></span></a><?php endforeach;?></div><?php if(!$events)ns_blank();?></section><?php endif;ns_foot();?>